<?php use Hls\Http\View as V; ?><p class="field-hint audit-note">100 catatan terbaru. Hanya administrator dengan izin audit dan cakupan global.</p><?php ob_start(); foreach ($rows as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><?= V::escape($row['created_at']) ?></td><td><?= V::escape($row['actor']??'Anonim') ?></td><td><?= V::escape($row['action']) ?></td><td><?= V::escape($row['entity'].' #'.($row['entity_id']??'')) ?></td><td><details><summary>Lihat detail</summary><pre><?= V::escape($row['detail']) ?></pre></details></td></tr><?php endforeach; echo $this->component('table',['caption'=>'Aktivitas fondasi','headers'=>['ID','Waktu WITA','Aktor','Aksi','Entitas','Detail'],'rowsHtml'=>ob_get_clean(),'hasRows'=>(bool)$rows]); echo $this->component('pagination',compact('pagination')); ?>